import thaumcraft.blocks.*;
import thaumcraft.entities.*;
import thaumcraft.registry.*;

/** Native damage pipeline, saved champion attributes, portal waves and last-giant drops. */
final class BossChampionVerification {
    static void run(ServerLevel level,BiConsumer<Boolean,String> check)throws Exception{
        var pos=new BlockPos(4020,160,80);var region=new AABB(pos).inflate(40);level.getChunkAt(pos);for(int x=-10;x<=10;x++)for(int z=-10;z<=10;z++){level.setBlock(pos.offset(x,-1,z),Blocks.STONE.defaultBlockState(),2);for(int y=0;y<8;y++)level.setBlock(pos.offset(x,y,z),Blocks.AIR.defaultBlockState(),2);}
        var cleanup=new ArrayList<Entity>();
        try{
            check.accept(ChampionSystem.NAMES.length==13&&Arrays.equals(ChampionSystem.EFFECT_TYPES,new int[]{-1,2,2,-1,1,0,1,0,1,1,1,1,2}),"all thirteen original modifier IDs and effect phases retained");
            for(int type=0;type<13;type++){
                var mob=EntityType.ZOMBIE.create(level);cleanup.add(mob);mob.moveTo(pos.getCenter());mob.setNoAi(true);double baseDamage=mob.getAttributeValue(Attributes.ATTACK_DAMAGE),baseSpeed=mob.getAttributeValue(Attributes.MOVEMENT_SPEED);mob.setHealth(1);ChampionSystem.makeChampion(mob,type,true);
                check.accept(ChampionSystem.modifier(mob)==type,"source modifier"+type+" stored in native synced attribute");check.accept(mob.getMaxHealth()==50&&mob.getHealth()==26&&mob.isPersistenceRequired(),"nonboss champion health buff30/heal25 and persistence"+type);
                check.accept(Math.abs(mob.getAttributeValue(Attributes.ATTACK_DAMAGE)-baseDamage*3*(type==3?4:1))<1e-8,"champion total damage multiplier3 and Mighty multiplier4 "+type);check.accept(Math.abs(mob.getAttributeValue(Attributes.MOVEMENT_SPEED)-baseSpeed*(type==0?1.3:1))<1e-8,"Bold base speed multiplier1.3 "+type);
                var tag=new CompoundTag();mob.saveWithoutId(tag);var restored=EntityType.ZOMBIE.create(level);cleanup.add(restored);restored.load(tag);check.accept(ChampionSystem.modifier(restored)==type&&restored.getMaxHealth()==50&&restored.getAttributeValue(Attributes.ATTACK_DAMAGE)==mob.getAttributeValue(Attributes.ATTACK_DAMAGE),"native champion modifier/buffs survive NBT reload"+type);
                if(type==5){check.accept(mob.getAbsorptionAmount()==10,"ward initial shield uses half base health20, not buffed health50");mob.setAbsorptionAmount(9.5f);mob.invulnerableTime=0;mob.tickCount=25;NeoForge.EVENT_BUS.post(new EntityTickEvent.Post(mob));check.accept(mob.getAbsorptionAmount()==10.5f,"warded native tick allows source fractional overshoot");mob.setAbsorptionAmount(9);mob.invulnerableTime=1;mob.tickCount=50;NeoForge.EVENT_BUS.post(new EntityTickEvent.Post(mob));check.accept(mob.getAbsorptionAmount()==9,"ward recharge waits through damage immunity");}
                if(type==7){mob.setHealth(20);mob.tickCount=19;NeoForge.EVENT_BUS.post(new EntityTickEvent.Post(mob));check.accept(mob.getHealth()==20,"Undying does not heal on intermediate tick");mob.tickCount=20;NeoForge.EVENT_BUS.post(new EntityTickEvent.Post(mob));check.accept(mob.getHealth()==21,"Undying heals one each20 ticks");}
            }
            var creep=EntityType.CREEPER.create(level);cleanup.add(creep);ChampionSystem.makeChampion(creep,false);check.accept(ChampionSystem.modifier(creep)==0,"forced Creeper champion always Bold");
            var cow=EntityType.COW.create(level);cleanup.add(cow);cow.moveTo(pos.getCenter().add(0,0,3));cow.setNoAi(true);cow.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);cow.setHealth(200);level.addFreshEntity(cow);
            var armored=EntityType.ZOMBIE.create(level);cleanup.add(armored);armored.moveTo(pos.getCenter());armored.setNoAi(true);ChampionSystem.makeChampion(armored,2,false);armored.getAttribute(Attributes.ARMOR).setBaseValue(0);float hp=armored.getHealth();armored.hurt(level.damageSources().mobAttack(cow),25);check.accept(armored.getHealth()==hp-19,"Armored incoming native damage25 reduced to19 before armor");
            var spined=EntityType.ZOMBIE.create(level);cleanup.add(spined);ChampionSystem.makeChampion(spined,1,false);cow.invulnerableTime=0;float before=cow.getHealth();spined.hurt(level.damageSources().mobAttack(cow),1);float returned=before-cow.getHealth();check.accept(returned>=1&&returned<=3,"Spined incoming hit deals real1..3 thorns damage");cow.invulnerableTime=0;before=cow.getHealth();spined.invulnerableTime=0;spined.hurt(level.damageSources().thorns(cow),2);check.accept(cow.getHealth()==before,"Spined thorns source does not recursively retaliate");
            var vampire=EntityType.ZOMBIE.create(level);cleanup.add(vampire);ChampionSystem.makeChampion(vampire,11,false);vampire.setHealth(10);cow.invulnerableTime=0;cow.hurt(level.damageSources().mobAttack(vampire),10);check.accept(vampire.getHealth()==15,"Vampiric damage pipeline heals half raw incoming10");cow.invulnerableTime=0;cow.hurt(level.damageSources().mobAttack(vampire),1);check.accept(vampire.getHealth()==17,"Vampiric minimum heal2");
            for(int type:new int[]{4,8,9,10}){var attacker=EntityType.ZOMBIE.create(level);cleanup.add(attacker);ChampionSystem.makeChampion(attacker,type,false);for(int i=0;i<80;i++){cow.invulnerableTime=0;cow.setHealth(200);cow.hurt(level.damageSources().mobAttack(attacker),1);}boolean effect=switch(type){case 4->cow.hasEffect(MobEffects.WITHER)&&cow.getEffect(MobEffects.WITHER).getDuration()==200;case 8->cow.isOnFire();case 9->cow.hasEffect(MobEffects.HUNGER)&&cow.getEffect(MobEffects.HUNGER).getDuration()==500;case 10->cow.hasEffect(MobEffects.POISON)&&cow.getEffect(MobEffects.POISON).getDuration()==100;default->false;};check.accept(effect,"modifier"+type+" applied source effect through actual native damage");}
            var infested=EntityType.ZOMBIE.create(level);cleanup.add(infested);infested.moveTo(pos.getCenter());ChampionSystem.makeChampion(infested,12,false);for(int i=0;i<80;i++)ChampionSystem.defense(infested,cow,level.damageSources().mobAttack(cow),1,12);var spiders=level.getEntitiesOfClass(TaintSpider.class,region);cleanup.addAll(spiders);check.accept(!spiders.isEmpty()&&spiders.stream().allMatch(s->s.getY()==infested.getY()+infested.getBbHeight()/2f),"Infested creates original registered spiderlings at half body height");
            for(var difficulty:new Difficulty[]{Difficulty.EASY,Difficulty.NORMAL,Difficulty.HARD})for(boolean enabled:new boolean[]{false,true})for(int roll:new int[]{0,50,99}){int expected=roll;if(difficulty==Difficulty.EASY||!enabled)expected+=2;if(difficulty==Difficulty.HARD&&enabled)expected-=2;expected-=3;expected-=enabled?2:1;expected-=enabled?10:3;expected-=199;check.accept(ChampionSystem.selectionScore(roll,difficulty,enabled,true,true,true,200)==expected,"source selection modifiers "+difficulty+"/enabled"+enabled+"/roll"+roll);}
            var leader=R5Entities.CULTIST_LEADER.get().create(level);cleanup.add(leader);leader.moveTo(pos.getCenter());leader.finalizeSpawn(level,level.getCurrentDifficultyAt(pos),MobSpawnType.COMMAND,null);check.accept(leader.getMaxHealth()==125&&leader.getAttributeValue(Attributes.ATTACK_DAMAGE)==5&&leader.getAttributeValue(Attributes.MOVEMENT_SPEED)==.32,"leader source base combat attributes");check.accept(leader.getItemBySlot(EquipmentSlot.HEAD).is(R5Content.CULTIST_ARMOR.get("cultist_leader_helmet").get())&&leader.getItemBySlot(EquipmentSlot.CHEST).is(R5Content.CULTIST_ARMOR.get("cultist_leader_chestplate").get())&&leader.getItemBySlot(EquipmentSlot.LEGS).is(R5Content.CULTIST_ARMOR.get("cultist_leader_leggings").get()),"leader equips all original leader plates");ChampionSystem.makeChampion(leader,3,true);check.accept(leader.getMaxHealth()==125&&leader.getAttributeValue(Attributes.ATTACK_DAMAGE)==20&&leader.hasCustomName(),"common boss skips generic health/damage buffs but retains Mighty and title");leader.performRangedAttack(cow,1);var red=level.getEntitiesOfClass(GolemOrb.class,region);cleanup.addAll(red);check.accept(red.size()==1&&red.get(0).red()&&red.get(0).getOwner()==leader&&red.get(0).homingTarget()==cow,"leader fires registered source red homing orb");
            var portal=R5Entities.CULTIST_PORTAL.get().create(level);cleanup.add(portal);portal.moveTo(pos.getCenter().add(12,0,0));portal.setNoAi(true);level.addFreshEntity(portal);check.accept(portal.getMaxHealth()==500&&portal.getAttributeValue(Attributes.ARMOR)==5&&portal.fireImmune()&&!portal.isPushable()&&portal.canBeCollidedWith(),"portal500HP/armour5/fire immunity and stationary collision");var start=portal.position();portal.move(MoverType.SELF,new net.minecraft.world.phys.Vec3(1,2,3));check.accept(portal.position().equals(start),"portal cannot move even with explicit movement");check.accept(!portal.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.POISON,100)),"portal rejects potion effects");for(int i=0;i<40;i++){portal.tickCount++;portal.tick();}for(var direction:new net.minecraft.core.Direction[]{net.minecraft.core.Direction.NORTH,net.minecraft.core.Direction.SOUTH,net.minecraft.core.Direction.WEST,net.minecraft.core.Direction.EAST}){var b=new BlockPos((int)portal.getX()-direction.getStepX()*6,(int)portal.getY(),(int)portal.getZ()+direction.getStepZ()*6);check.accept(level.getBlockState(b).is(R4Content.BANNER.get()),"portal creates source cardinal invasion banner"+direction);}
            for(int i=0;i<145;i++){portal.tickCount++;portal.tick();}check.accept(level.getBlockStates(new AABB(portal.blockPosition()).inflate(5)).anyMatch(s->s.is(R5Content.LOOT_CRATE.get())),"portal preparation creates native loot crates");portal.spawnMinions();var minions=level.getEntitiesOfClass(Cultist.class,region);cleanup.addAll(minions);check.accept(!minions.isEmpty()&&minions.stream().anyMatch(m->m.getRestrictRadius()==32&&m.getRestrictCenter().equals(portal.blockPosition())),"portal native waves set minion32-block home");check.accept(portal.getTiming()==minions.stream().filter(m->new AABB(portal.position(),portal.position()).inflate(32).intersects(m.getBoundingBox())).count()*20,"portal wave wait equals20 per cultist in original box");portal.spawnBoss();var leaders=level.getEntitiesOfClass(CultistLeader.class,region);cleanup.addAll(leaders);check.accept(leaders.stream().anyMatch(m->m.getRestrictRadius()==32&&m.hasCustomName()),"portal summons titled champion leader with source home");var saved=new CompoundTag();saved.putInt("stage",13);portal.readAdditionalSaveData(saved);float portalHP=portal.getHealth();portal.spawnMinions();check.accept(portal.getHealth()>=portalHP-9&&portal.getHealth()<=portalHP-5,"after stage12 each minion consumes5..9 portal health");var save=new CompoundTag();portal.addAdditionalSaveData(save);var reloaded=R5Entities.CULTIST_PORTAL.get().create(level);cleanup.add(reloaded);reloaded.readAdditionalSaveData(save);check.accept(reloaded.getStage()==13&&reloaded.getStageCounter()==200&&reloaded.pulse==0,"portal persists stage but resets transient200 countdown/pulse");
            var giant=R5Entities.TAINTACLE_GIANT.get().create(level);cleanup.add(giant);giant.moveTo(pos.getCenter().add(-8,0,0));check.accept(giant.getMaxHealth()==125&&giant.getAttributeValue(Attributes.ATTACK_DAMAGE)==9&&giant.getBbHeight()==6&&giant.getBbWidth()==1.1f,"giant source base combat attributes and dimensions");giant.finalizeSpawn(level,level.getCurrentDifficultyAt(pos),MobSpawnType.COMMAND,null);check.accept(ChampionSystem.modifier(giant)>=0&&giant.getMaxHealth()==155&&giant.isPersistenceRequired(),"giant is generic champion125+30 and persists after spawn");check.accept(!giant.checkSpawnRules(level,MobSpawnType.NATURAL)&&!giant.removeWhenFarAway(10000),"giant disallows natural spawn and distance despawn");giant.invulnerableTime=0;giant.hurt(level.damageSources().generic(),80);check.accept(giant.getAnger()==200&&giant.hasEffect(MobEffects.DAMAGE_RESISTANCE),"giant enrage triggered by source raw high hit");var giant2=R5Entities.TAINTACLE_GIANT.get().create(level);cleanup.add(giant2);giant2.moveTo(giant.position().add(47,47,47));normal(giant2);level.getChunkAt(giant2.blockPosition());level.addFreshEntity(giant2);var drop=TaintacleGiant.class.getDeclaredMethod("dropCustomDeathLoot",ServerLevel.class,net.minecraft.world.damagesource.DamageSource.class,boolean.class);drop.setAccessible(true);int prior=level.getEntitiesOfClass(SpecialItemEntity.class,region).size();drop.invoke(giant,level,level.damageSources().generic(),true);check.accept(level.getEntitiesOfClass(SpecialItemEntity.class,region).size()==prior,"other giant in original48-block box suppresses duplicate pearl, including diagonal");giant2.discard();drop.invoke(giant,level,level.damageSources().generic(),true);var pearls=level.getEntitiesOfClass(SpecialItemEntity.class,region);cleanup.addAll(pearls);check.accept(pearls.size()==prior+1&&pearls.stream().anyMatch(p->p.getItem().is(R3Equipment.PRIMAL_PEARL.get())),"last giant drops expiring special primal pearl");
        }finally{cleanup.forEach(Entity::discard);level.getEntitiesOfClass(Cultist.class,region).forEach(Entity::discard);level.getEntitiesOfClass(TaintSpider.class,region).forEach(Entity::discard);}
    }
    static void normal(Mob mob){var attr=mob.getAttribute(ChampionSystem.MODIFIER);attr.addPermanentModifier(new AttributeModifier(ResourceLocation.parse("thaumcraft:verification_normal"),1,AttributeModifier.Operation.ADD_VALUE));}
}
